import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as i,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Kimi Code 学习地图","description":"Kimi Code 是月之暗面面向开发者的编程助手套件（CLI + VS Code）。同厂的 Kimi 对话 / Work / Claw 不是这个产品。本目录只教你把 Kimi Code 装上、登录、对着真实仓库干活。","frontmatter":{"title":"Kimi Code 学习地图","description":"Kimi Code 是月之暗面面向开发者的编程助手套件（CLI + VS Code）。同厂的 Kimi 对话 / Work / Claw 不是这个产品。本目录只教你把 Kimi Code 装上、登录、对着真实仓库干活。","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"zh/products/kimi-code/index.md","filePath":"zh/products/kimi-code/index.md","lastUpdated":1787110548000}'),r={name:"zh/products/kimi-code/index.md"};function d(n,t,s,c,l,h){return i(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="kimi-code-学习地图" tabindex="-1">Kimi Code 学习地图 <a class="header-anchor" href="#kimi-code-学习地图" aria-label="Permalink to &quot;Kimi Code 学习地图&quot;">​</a></h1><blockquote><p><strong>Kimi Code</strong> 是 Kimi 会员里专为开发者提供的智能编程服务。官方形态是 <strong>CLI</strong>、<strong>VS Code 扩展</strong>，以及把同一套模型接到第三方 Agent 的 <strong>API Key</strong>。</p><p>产品总览原文（<a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">www.kimi.com/code/docs</a>）： 「通过 CLI、VS Code 扩展插件等产品形态，为开发者提供代码阅读、文件编辑、命令执行等 AI 辅助能力。」</p></blockquote><h2 id="写给谁-先决条件" tabindex="-1">写给谁 / 先决条件 <a class="header-anchor" href="#写给谁-先决条件" aria-label="Permalink to &quot;写给谁 / 先决条件&quot;">​</a></h2><ul><li><strong>写给谁</strong>：已经会用终端或 VS Code 的前端工程师，想要一个国内直连的 Claude Code 对位物。</li><li><strong>先决条件</strong>：macOS / Linux / Windows；一个 Kimi 账号（会员订阅或可调用的 API Key）。CLI 脚本安装<strong>不需要</strong>预装 Node.js；选 npm 通道则需要 <strong>Node.js 22.19.0+</strong>。</li><li><strong>非目标</strong>：不教 Kimi 网页对话、Kimi Work 桌面 Agent、Kimi Claw 云端机器人；不教模型内部机制（去 Learn LLM）；不把旧版 Python <code>kimi-cli</code> 当主线。</li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>月之暗面官方一级入口必须先对账。本目录<strong>只展开 Kimi Code</strong>。对话 / Work / Claw 各占一行，链到将有的 <a href="/zh/products/kimi/">Kimi 家族页</a>。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>Kimi Code</strong>（产品落地）</td><td><a href="https://www.kimi.com/code" target="_blank" rel="noreferrer">www.kimi.com/code</a></td><td>本目录主路径</td></tr><tr><td><strong>Kimi Code 文档总览</strong></td><td><a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">www.kimi.com/code/docs</a></td><td>本页</td></tr><tr><td><strong>Kimi Code CLI</strong></td><td><a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">产品文档 · 开始使用</a> · <a href="https://moonshotai.github.io/kimi-code/zh/guides/getting-started" target="_blank" rel="noreferrer">CLI 文档站</a></td><td><a href="./kimi-code.html">教程</a></td></tr><tr><td><strong>Kimi Code for VS Code</strong></td><td><a href="https://www.kimi.com/code/docs/kimi-code-for-vscode/getting-started" target="_blank" rel="noreferrer">产品文档 · 快速开始</a> · <a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">Marketplace</a></td><td><a href="./kimi-code.html#kimi-code-for-vs-code">教程 · VS Code</a></td></tr><tr><td><strong>Kimi Code 控制台</strong></td><td><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">www.kimi.com/code/console</a></td><td>地图一行：额度、API Key、设备</td></tr><tr><td><strong>Kimi Code API</strong>（接到第三方工具）</td><td>总览里的 Base URL 表</td><td><a href="./kimi-code.html#把-kimi-code-接到第三方工具">教程 · API</a> · <a href="./kimi-code-cheatsheet.html">速查</a></td></tr><tr><td><strong>Kimi</strong>（网页 / App）</td><td><a href="https://www.kimi.com" target="_blank" rel="noreferrer">www.kimi.com</a> · <a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">产品对照</a></td><td>一行 → <a href="/zh/products/kimi/">Kimi 家族</a>（#70）</td></tr><tr><td><strong>Kimi Work</strong></td><td><a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">产品对照</a> · <a href="https://www.kimi.com/zh-cn/products/download" target="_blank" rel="noreferrer">下载页桌面端</a></td><td>一行 → <a href="/zh/products/kimi/">Kimi 家族</a></td></tr><tr><td><strong>Kimi Claw</strong></td><td><a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">产品对照</a></td><td>一行 → <a href="/zh/products/kimi/">Kimi 家族</a></td></tr><tr><td><strong>Kimi 开放平台</strong></td><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <code>platform.kimi.com</code> / <code>platform.kimi.ai</code></td><td>一行：按量 API，不是本目录</td></tr><tr><td>旧版 Python <strong>kimi-cli</strong></td><td><a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New 对照表</a></td><td><a href="./kimi-code.html#附录从-python-kimi-cli-迁移">教程附录</a></td></tr></tbody></table><p>来源：<a href="https://www.kimi.com/zh-hans/help/others/product-comparison" target="_blank" rel="noreferrer">产品对照</a>、<a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">Kimi Code 总览</a>、<a href="https://www.kimi.com/zh-cn/products/download" target="_blank" rel="noreferrer">下载页</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月之暗面 / Kimi 家族</span></span>
<span class="line"><span>├── Kimi（网页 / App）— 对话 + Agent + Deep Research</span></span>
<span class="line"><span>├── Kimi Work — 桌面本地 Agent（文件 / 跨应用 / 长任务）</span></span>
<span class="line"><span>├── Kimi Code — 开发者编程套件（本目录）</span></span>
<span class="line"><span>│   ├── CLI（命令 \`kimi\`）</span></span>
<span class="line"><span>│   ├── VS Code 扩展（moonshot-ai.kimi-code）</span></span>
<span class="line"><span>│   └── API Key → 第三方 Coding Agent</span></span>
<span class="line"><span>├── Kimi Claw — 零部署云端自动化 / 机器人</span></span>
<span class="line"><span>└── 开放平台 — 按量 HTTP API（不是 Coding Agent 产品）</span></span></code></pre></div><p><strong>容易撞名：</strong></p><ul><li><strong>Kimi Code ≠ Kimi 对话 ≠ Kimi Work ≠ Kimi Claw</strong>。对照页原文：Code 面向开发者、写代码、维护代码库；入口是 CLI 和 VS Code 扩展。</li><li><strong>命令 <code>kimi</code> ≠ 产品名 Kimi Code</strong>。装的是 Kimi Code CLI，敲下去的可执行文件叫 <code>kimi</code>。</li><li><strong><code>~/.kimi-code/</code> ≠ <code>~/.kimi/</code></strong>。前者是现行 Node CLI 的数据根；后者是旧 Python <code>kimi-cli</code>。</li><li><strong><code>api.kimi.com/coding</code> ≠ <code>api.moonshot.cn/v1</code></strong>。会员 Coding 额度 和 开放平台按量是两套账号，Key 不通用（<a href="https://www.kimi.ai/zh-hans/help/kimi-code/cli-getting-started" target="_blank" rel="noreferrer">帮助中心 FAQ</a>）。</li><li><strong><code>kimi acp</code> ≠ VS Code 扩展</strong>。ACP 把 CLI 嵌进 Zed / JetBrains / Paseo；VS Code 另有第一方插件，且官方标明「适配中」。</li></ul><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在真实仓库里写代码 / 修 bug / 重构 / 跑测试</span></span>
<span class="line"><span>│   └── → Kimi Code</span></span>
<span class="line"><span>│       ├── 在终端？ → CLI（\`kimi\`）</span></span>
<span class="line"><span>│       ├── 在 VS Code？ → 先读官方「仅旧版 Python CLI 用户可新装」横幅，再决定扩展还是终端</span></span>
<span class="line"><span>│       ├── 在 Zed / JetBrains？ → \`kimi acp\`（不是 VS Code 插件）</span></span>
<span class="line"><span>│       └── 已经在用 Claude Code / Codex / OpenCode？ → 用 Kimi Code API Key 接进去</span></span>
<span class="line"><span>├── 聊天 / 写作 / 搜索 / 建站 / PPT / Deep Research</span></span>
<span class="line"><span>│   └── → [Kimi 网页 / App](/zh/products/kimi/)</span></span>
<span class="line"><span>├── 读写本机文件、跨桌面应用、跑长任务</span></span>
<span class="line"><span>│   └── → [Kimi Work](/zh/products/kimi/)</span></span>
<span class="line"><span>├── 7×24 云端机器人、接飞书 / 微信</span></span>
<span class="line"><span>│   └── → [Kimi Claw](/zh/products/kimi/)</span></span>
<span class="line"><span>└── 在自己的产品里按量调模型</span></span>
<span class="line"><span>    └── → Kimi 开放平台（不是本目录）</span></span></code></pre></div><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 装上能跑</td><td><a href="./kimi-code.html">教程 · 安装与登录</a></td><td>15 分钟内第一次对话</td></tr><tr><td>2. 敢让它改代码</td><td><a href="./kimi-code.html#交互审批与三种权限模式">教程 · TUI 与审批</a></td><td>分清 Plan / YOLO / Auto</td></tr><tr><td>3. 选对入口</td><td><a href="./kimi-code.html#kimi-code-for-vs-code">教程 · VS Code / ACP / API</a></td><td>不要进错门</td></tr><tr><td>4. 回查参数</td><td><a href="./kimi-code-cheatsheet.html">速查表</a></td><td>命令、slash、模型 ID、Base URL</td></tr><tr><td>5. 从旧 CLI 过来</td><td><a href="./kimi-code.html#附录从-python-kimi-cli-迁移">迁移附录</a></td><td><code>kimi migrate</code>，不要继续维护 Python 线</td></tr></tbody></table><h2 id="功能速查" tabindex="-1">功能速查 <a class="header-anchor" href="#功能速查" aria-label="Permalink to &quot;功能速查&quot;">​</a></h2><p>只列官方文档已经写明的能力。细节进教程或官方页。</p><table tabindex="0"><thead><tr><th>能力</th><th>一句话</th><th>官方页</th></tr></thead><tbody><tr><td>交互式 TUI</td><td>项目目录跑 <code>kimi</code></td><td><a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">开始使用</a></td></tr><tr><td>Headless</td><td><code>kimi -p &quot;…&quot;</code>，可加 <code>--output-format stream-json</code></td><td><a href="https://moonshotai.github.io/kimi-code/zh/reference/kimi-command" target="_blank" rel="noreferrer">kimi 命令</a></td></tr><tr><td>Plan 模式</td><td><code>Shift-Tab</code> 或 <code>/plan</code>，先方案再改文件</td><td><a href="https://moonshotai.github.io/kimi-code/zh/guides/interaction" target="_blank" rel="noreferrer">交互与输入</a></td></tr><tr><td>YOLO / Auto</td><td><code>/yolo</code> 跳过普通审批；<code>/auto</code> 无人值守且不再提问</td><td>同上</td></tr><tr><td>会话</td><td><code>-c</code> / <code>--continue</code>，<code>/sessions</code>，<code>/fork</code>，<code>kimi export</code></td><td><a href="https://moonshotai.github.io/kimi-code/zh/guides/sessions" target="_blank" rel="noreferrer">会话</a></td></tr><tr><td>ACP</td><td><code>kimi acp</code> 给 Zed / JetBrains / Paseo</td><td><a href="https://moonshotai.github.io/kimi-code/zh/guides/ides" target="_blank" rel="noreferrer">在 IDE 中使用</a></td></tr><tr><td>Skills / MCP / Hooks / Plugins</td><td>扩展点；内置 Skill 直接是 <code>/name</code></td><td><a href="https://moonshotai.github.io/kimi-code/zh/customization/mcp" target="_blank" rel="noreferrer">定制化</a></td></tr><tr><td>Subagent</td><td>内置 <code>coder</code> / <code>explore</code> / <code>plan</code></td><td><a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">README</a> · <a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New</a></td></tr><tr><td>Goal</td><td><code>/goal</code> 跨轮次推进一个持久目标</td><td><a href="https://moonshotai.github.io/kimi-code/zh/guides/goals" target="_blank" rel="noreferrer">使用目标模式</a></td></tr><tr><td>视频输入</td><td>输入框粘贴视频（macOS/Linux <code>Ctrl-V</code>，Windows <code>Alt-V</code>）</td><td><a href="https://moonshotai.github.io/kimi-code/zh/guides/interaction" target="_blank" rel="noreferrer">交互与输入</a></td></tr><tr><td>模型</td><td><code>k3</code> / <code>kimi-for-coding</code> / <code>kimi-for-coding-highspeed</code></td><td><a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">模型配置</a></td></tr></tbody></table><h2 id="会员与额度-只抄官方-不猜价格" tabindex="-1">会员与额度（只抄官方，不猜价格） <a class="header-anchor" href="#会员与额度-只抄官方-不猜价格" aria-label="Permalink to &quot;会员与额度（只抄官方，不猜价格）&quot;">​</a></h2><ul><li>CLI / VS Code / 第三方工具的请求<strong>计入同一套 Kimi Code 额度</strong>（<a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">会员权益</a>）。</li><li>额度从订阅日起 <strong>每 7 天刷新</strong>，未用完不累积；另有 <strong>每 5 小时滚动窗口</strong>。</li><li>与 Kimi 会员月总额度共享：月额度打满后 Code 额度会冻结。</li><li>对照页补充：会员功能共用额度池；Kimi Code <strong>另有</strong>仅作用于 Code 的 5 小时 / 每周速率限制。</li><li>产品文档横幅：<strong>新会员体系即将上线</strong>，Code 权益将与 Kimi 会员拆分。订阅中的用户不受影响。档位与价格以 <a href="https://www.kimi.com/membership/pricing" target="_blank" rel="noreferrer">Kimi 会员页</a> 为准，本站不写死金额。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>打开 <a href="./kimi-code.html">Kimi Code 教程</a>，用官方脚本装 CLI。</li><li>参数和模型 ID 去 <a href="./kimi-code-cheatsheet.html">速查表</a>。</li><li>官方深读从 <a href="https://www.kimi.com/code/docs/" target="_blank" rel="noreferrer">code/docs</a> 和 <a href="https://moonshotai.github.io/kimi-code/zh/" target="_blank" rel="noreferrer">CLI 文档站</a> 进。</li></ol>`,22)])])}const w=e(r,[["render",d]]);export{f as __pageData,w as default};
